package com.autojobapply.tracking; import com.autojobapply.model.*; import java.nio.file.*; import java.util.List;
public final class GreenhousePersistenceTest { public static void main(String[] a)throws Exception{Path p=Files.createTempFile("greenhouse",".db");try(ApplicationTracker t=new ApplicationTracker(p)){t.initialize();t.saveEmployer("x","Co","u","a","fixture",true);t.saveEmployer("x","Co2","u","a","fixture",true);Job j=new Job("Greenhouse","Co2","Staff","SF","description","1","u","u");t.saveGreenhouseJob("x",j);t.saveGreenhouseJob("x",j);t.record(new ScoredJob(j,85,List.of("java"),List.of(),true,"matched",List.of()),ApplicationStatus.MATCHED,null);t.enqueue("x",new ScoredJob(j,85,List.of("java"),List.of(),true,"matched",List.of()));ScoredJob queued=t.queuedJob("co2|1").orElseThrow(()->new AssertionError("queued job"));if(!"description".equals(queued.job().description())||queued.score()!=85)throw new AssertionError("queued details");if(t.greenhouseJobCount()!=1)throw new AssertionError("duplicate job");}try(ApplicationTracker t=new ApplicationTracker(p)){if(t.greenhouseJobCount()!=1)throw new AssertionError("reopen");}Files.deleteIfExists(p);System.out.println("GREENHOUSE_PERSISTENCE_TEST_PASSED");}}
